const runScript=(name,{timeoutMs=null,env={}}={})=>{
  const timeout=Number(timeoutMs??process.env.CONTROLLING_COMPLETION_CHILD_TIMEOUT_MS??120000);
  assert(Number.isFinite(timeout)&&timeout>0&&timeout<=600000,`${name} child timeout must be between 1 and 600000 ms.`);
  const result=spawnSync(process.execPath,[path.join(root,name)],{cwd:root,encoding:'utf8',env:{...process.env,...env},timeout:Math.floor(timeout)});
  assert(!result.error,`${name} could not complete within ${timeout} ms: ${result.error?.message||result.error}`);
  assert.equal(result.status,0,`${name} failed: ${result.stderr||result.stdout}`);
  const lines=result.stdout.trim().split(/\r?\n/);let parsed=null;
  for(let index=lines.length-1;index>=0&&!parsed;index--)try{parsed=JSON.parse(lines.slice(index).join('\n'));}catch{}
  return parsed||{stdout:result.stdout.trim()};
};
