  engine.registerGeneratedPrompt(p,prompt);engine.reserveOperation(p,{preparedReservation,promptId:prompt.instructionId});p.revision=preparedReservation.expectedRevision;
  const envelope=conditionalStage4Envelope(p,prompt),text=JSON.stringify(envelope),prepared=ingestion.prepare(p,{stage:4,text,promptRecord:prompt});
  assert(prepared.validation.valid,`Valid Stage 4 conditional-activation response was rejected: ${JSON.stringify(prepared.validation.issues)}`);
  const proposedTarget=prepared.proposal.canonicalRecords.propositions.find(record=>record.temporaryKey==='conditional-target'),proposedActivation=prepared.proposal.canonicalRecords.propositions.find(record=>record.temporaryKey==='activation-source');
  assert(proposedTarget&&proposedActivation,'Ingestion omitted a conditional target or activation proposition.');
  assert.equal(proposedTarget.fields.ACTIVATION_PROPOSITION_ID,proposedActivation.id,'Ingestion did not application-resolve the activation tempKey in canonical fields.');
  assert.equal(proposedTarget.relationships.ACTIVATION_PROPOSITION_ID,proposedActivation.id,'Ingestion did not application-resolve the activation tempKey in canonical relationships.');
  const committed=ingestion.commit(prepared.project,prepared.proposal.proposalId,{operator:'CONTROLLING_COMPLETION_VERIFIER'}),canonicalTarget=engine.recordsForCurrentScope(committed.project,'propositions').find(record=>engine.recordId(record,'propositions')===proposedTarget.id),canonicalActivation=engine.recordsForCurrentScope(committed.project,'propositions').find(record=>engine.recordId(record,'propositions')===proposedActivation.id),manifestEntry=committed.manifest.entries.find(item=>item.jsonPointer==='/records/propositions/0/relationships/ACTIVATION_PROPOSITION_ID');
