  assert.equal(manifestEntry?.relationshipTargetId,canonicalActivation.id);
  assert.equal(Object.hasOwn(envelope.records.propositions[0].fields,'ACTIVATION_PROPOSITION_ID'),false,'The response illegally supplied the application-owned activation field.');
