await verify(217,'redaction creates linked new artifact',async()=>{const p=project('REDACTION'),sourceBytes=new TextEncoder().encode('secret and public content'),redactedBytes=new TextEncoder().encode('[REDACTED] and public content'),sourceSha256=await hash.sha256Bytes(sourceBytes),redactedSha256=await hash.sha256Bytes(redactedBytes),sourceRecord=add(p,'artifacts',{FILENAME:'source.txt',DISCLOSURE_CLASSIFICATION:'RESTRICTED',SHA256:sourceSha256,BYTE_SIZE:sourceBytes.byteLength,AVAILABILITY:'BYTES_PERSISTED_AND_VERIFIED'},{id:'ARTIFACT-REDACTION-SOURCE',stage:1}),beforeHistory=p.projectData.history.length,realStore=globalThis.closedLoopProjectStore;assert.equal(p.projectData.redactionRecords,undefined,'Blank canonical state unexpectedly initialized the retired redactionRecords authority array.');try{globalThis.closedLoopProjectStore={...realStore,getArtifact:async artifactId=>artifactId===sourceRecord.id?{artifactId,jobId:p.job.JOB_ID,blob:new Blob([sourceBytes]),disclosureClassification:'RESTRICTED'}:null,stageAttachment:async options=>({stagingId:'STAGING-REDACTION',artifactId:'STAGING-REDACTION',targetArtifactId:options.targetArtifactId,filename:options.filename,mediaType:options.mediaType,byteSize:redactedBytes.byteLength,sha256:redactedSha256,lineage:options.lineage,disclosureClassification:options.disclosureClassification}),commitProjectWithStagedAttachments:async options=>{assert.deepEqual(options.stagingIds,['STAGING-REDACTION']);options.mutator(p);return {project:p,receipt:{status:'COMMITTED'}};}};const result=await engine.createRedactedArtifact(p,{sourceArtifactId:sourceRecord.id,artifactId:'ARTIFACT-REDACTED',blob:new Blob([redactedBytes],{type:'text/plain'}),filename:'redacted.txt',mediaType:'text/plain',redactionDescription:'Remove the restricted token.',disclosureClassification:'RESTRICTED',expectedRevision:p.revision});const derived=engine.records(p,'artifacts').find(record=>engine.recordId(record,'artifacts')==='ARTIFACT-REDACTED'),newHistory=p.projectData.history.slice(beforeHistory),byteEvents=newHistory.filter(record=>record.type==='ARTIFACT_BYTES_REGISTERED'&&record.artifactId==='ARTIFACT-REDACTED'),lineageEvents=newHistory.filter(record=>record.type==='ARTIFACT_REDACTION_DERIVATION'&&record.sourceArtifactId===sourceRecord.id&&record.redactedArtifactId==='ARTIFACT-REDACTED'),link=lineageEvents[0];assert(derived);const lineage=JSON.parse(String(engine.recordValue(derived,'NOTES')||'{}'));assert.equal(lineage.REDACTED_FROM,sourceRecord.id);assert.equal(lineage.sourceSha256,sourceSha256);assert.deepEqual(newHistory.map(record=>record.type),['ARTIFACT_BYTES_REGISTERED','ARTIFACT_REDACTION_DERIVATION']);assert.equal(byteEvents.length,1);assert.equal(lineageEvents.length,1);assert.equal(link.relationship,'REDACTED_FROM');assert.equal(link.sourceSha256,sourceSha256);assert.equal(link.redactedSha256,redactedSha256);assert.equal(p.projectData.redactionRecords,undefined,'Redaction recreated the retired gate-bearing array.');assert.equal(result.relationship,'REDACTED_FROM');return {sourceArtifactId:sourceRecord.id,redactedArtifactId:result.artifactId,byteCustodyHistoryEventId:byteEvents[0].eventId,redactionHistoryEventId:link.eventId};}finally{globalThis.closedLoopProjectStore=realStore;}},{apis:['createRedactedArtifact','stageAttachment','commitProjectWithStagedAttachments'],mode:'BEHAVIOR_WITH_IN_MEMORY_CUSTODY_ADAPTER'});
