// 69.9 Independence, statistics, and environment.
function tenRunFixture({reuseExternal=false,contaminate=false}={}){
  const p=project('TEN-RUN'),iterationId='ITER-TEN',candidateId='CANDIDATE-ONE',scope={...engine.currentScope(p),iterationId,candidateId};
  add(p,'iterations',{ITERATION_ID:iterationId,CANDIDATE_ID:candidateId,STATUS:'FROZEN'},{id:iterationId,scope});
  for(let index=1;index<=10;index++){
    const runId=`RUN-${index}`,contextId=`CONTEXT-${index}`,external=reuseExternal&&index===10?'EXTERNAL-1':`EXTERNAL-${index}`;
    add(p,'freshContexts',{CONTEXT_ID:contextId,RUN_ID:runId,EXTERNAL_CONTEXT_IDENTIFIER:external,AUTHORIZED_PROJECT_INPUTS:['CURRENT CANDIDATE'],CONTAMINATION_STATUS:contaminate&&index===1?'CONTAMINATED':'NONE'},{id:contextId,stage:11,scope});
    add(p,'runs',{RUN_ID:runId,ITERATION_ID:iterationId,CANDIDATE_ID:candidateId,CONTEXT_ID:contextId,EXECUTION_STATUS:'COMPLETED',CONTAMINATION_CHECK:'NONE'},{id:runId,stage:11,scope});
  }
  return {p,iterationId};
}
