// 69.10 Regression, release, delivery, and reopening.
let terminalLifecycleProof=null;
const terminalLifecycle=()=>{
  if(terminalLifecycleProof)return terminalLifecycleProof;
  const output=runScript('verify-terminal-delivery-lifecycle.mjs');
  assert.equal(output.terminalDeliveryLifecycle,'PASS');
  assert.equal(output.priorAuthorizationImmutable,true);
  assert.equal(output.currentWithdrawalAppended,true);
  assert.equal(output.withdrawalIdempotent,true);
  assert.equal(output.backupEvaluatorPure,true);
  terminalLifecycleProof=output;
  return output;
};
function authorizedDeliveryFixture(p,id){
  const delivery=add(p,'deliveryRecords',{JOB_ID:p.job.JOB_ID,DELIVERY_STATE:'AUTHORIZED',AUTHORIZED_ARTIFACT_IDS:['A'],AUTHORIZED_FILENAMES:['a.bin'],BYTE_SIZES:['1'],HASH_ALGORITHMS_AND_DIGESTS:[{artifactId:'A',hashAlgorithm:'SHA-256',digest:'a'.repeat(64),byteLength:1}],EXPECTED_PRECONDITION_REVISION:Number(p.revision||0),COMMITTED_PROJECT_REVISION:Number(p.revision||0)+1,EVENT_SEQUENCE:1,DELIVERY_RECORD_HASH:''},{id,stage:30});
  const deliveryRecordHash=hash.sha256Value(Object.fromEntries(Object.entries(delivery.fields).filter(([name])=>name!=='DELIVERY_RECORD_HASH')));
  delivery.fields.DELIVERY_RECORD_HASH=deliveryRecordHash;
  delivery.DELIVERY_RECORD_HASH=deliveryRecordHash;
  engine.refreshRecordHashes(delivery,'deliveryRecords');
  p.release.authorization='AUTHORIZED';
  p.release.authorizedArtifactIds=['A'];
  return delivery;
}
