await verify(286,'delivery record requires all terminal prerequisites and human intent',()=>{
  const evidencePath=String(process.env.FULL_CYCLE_TERMINAL_REPORT_PATH||'').trim();
  assert(evidencePath,'FULL_CYCLE_TERMINAL_REPORT_PATH is required; case 286 consumes the one prior legitimate full-cycle execution report and never seeds terminal state or replays the lifecycle.');
  const validated=readAndValidateFullCycleTerminalEvidence(evidencePath,{root,hash}),report=validated.report;
  let missingReportRejected=false,staleReportRejected=false,staleSourceRejected=false,forgedReportRejected=false;
  try{readAndValidateFullCycleTerminalEvidence(`${path.resolve(evidencePath)}.missing-${process.pid}`,{root,hash});}catch(error){missingReportRejected=/report is missing/i.test(String(error?.message||error));}
  const stale=JSON.parse(JSON.stringify(report));stale.generatedAt='2000-01-01T00:00:00.000Z';
  try{validateFullCycleTerminalEvidence(sealFullCycleTerminalEvidence(stale,hash),{root,hash});}catch(error){staleReportRejected=/stale by age/i.test(String(error?.message||error));}
  const staleSource=JSON.parse(JSON.stringify(report));staleSource.sourceIdentity.files[0].sha256='0'.repeat(64);staleSource.sourceIdentity.sourceSetSha256=hash.sha256Value(staleSource.sourceIdentity.files);
  try{validateFullCycleTerminalEvidence(sealFullCycleTerminalEvidence(staleSource,hash),{root,hash});}catch(error){staleSourceRejected=/source hashes are stale|do not match/i.test(String(error?.message||error));}
  const forged=JSON.parse(JSON.stringify(report));forged.terminal.deliveryRecord.fields.CONTROLLING_REASON=`${forged.terminal.deliveryRecord.fields.CONTROLLING_REASON} FORGED`;
  try{validateFullCycleTerminalEvidence(sealFullCycleTerminalEvidence(forged,hash),{root,hash});}catch(error){forgedReportRejected=/delivery record field hash is invalid/i.test(String(error?.message||error));}
  assert(missingReportRejected&&staleReportRejected&&staleSourceRejected&&forgedReportRejected,'Full-cycle evidence consumer did not reject every missing, stale, stale-source, and re-sealed forged report mutation.');
  return {schema:validated.schema,reportSha256:validated.reportSha256,sourceSetSha256:validated.sourceSetSha256,projectSha256:validated.projectSha256,deliveryId:validated.deliveryId,deliveryRecordHash:validated.deliveryRecordHash,terminalEvidenceHash:validated.terminalEvidenceHash,authorizedArtifactCount:validated.authorizedArtifactCount,missingReportRejected,staleReportRejected,staleSourceRejected,forgedReportRejected,secondLifecycleReplay:false};
},{apis:['terminalPrerequisites','createDeliveryRecord','recordBackupRestoreVerification'],mode:'EXECUTABLE_FULL_CYCLE_EVIDENCE_CONSUMER'});
await verify(287,'release-bearing mutation withdraws current delivery',()=>{const focused=terminalLifecycle(),p=project('WITHDRAW'),delivery=authorizedDeliveryFixture(p,'DELIVERY-1'),priorFieldsHash=hash.sha256Value(delivery.fields),priorDeliveryRecordHash=engine.recordValue(delivery,'DELIVERY_RECORD_HASH');engine.invalidateDownstream(p,'requirements','REQ-CHANGE','Current release-bearing requirements changed.');const active=p.projectData.deliveryRecords.filter(engine.isActiveRecord),withdrawals=active.filter(record=>engine.recordValue(record,'DELIVERY_STATE')==='WITHDRAWN_FOR_FUTURE_USE');assert.equal(engine.recordValue(delivery,'DELIVERY_STATE'),'AUTHORIZED');assert.equal(hash.sha256Value(delivery.fields),priorFieldsHash);assert.equal(engine.recordValue(delivery,'DELIVERY_RECORD_HASH'),priorDeliveryRecordHash);assert.equal(delivery.active,false);assert.equal(withdrawals.length,1);assert.equal(engine.recordValue(withdrawals[0],'PREVIOUS_DELIVERY_ID'),delivery.id);assert.equal(engine.recordValue(withdrawals[0],'LIFECYCLE_CHANGE_ID'),'REQ-CHANGE');assert.equal(withdrawals[0].source,'APPLICATION_DERIVED');assert.equal(p.release.authorization,'NOT AUTHORIZED');const deliveryCount=p.projectData.deliveryRecords.length,receiptCount=p.projectData.commandReceipts.length;engine.recalculate(p);assert.equal(p.projectData.deliveryRecords.length,deliveryCount);assert.equal(p.projectData.commandReceipts.length,receiptCount);return {focused,priorDeliveryId:delivery.id,withdrawalDeliveryId:withdrawals[0].id,priorAuthorizationImmutable:true,currentWithdrawalAppended:true};},{apis:['invalidateDownstream','withdrawDeliveryAuthorization','recalculate'],mode:'EXECUTABLE_LIFECYCLE_SUITE'});
await verify(288,'application does not claim physical-delivery undo',()=>includes('app-core.js','The application cannot undo a physical delivery that already occurred','later invalidation can only supersede or withdraw authorization for future use.'),{mode:'BROWSER_CONTRACT'});
