const supplemental=[];
async function supplement(name,check,apis=[]){try{const evidence=await check();supplemental.push({name,status:'PASS',apis,evidence:evidence??null});}catch(error){supplemental.push({name,status:'FAIL',apis,error:{name:error?.name||'Error',code:error?.code||null,message:String(error?.message||error)}});}}
await supplement('AMENDMENT_AND_INDEPENDENT_REVIEW_FAMILY_OWNERSHIP_CLOSURE',()=>{
  const families=['propositions','propositionEquivalenceReviews','applicabilityRecords','proofExpressions','proofObligations','semanticCoverageReviews','sourceSearchAdequacyReviews','requirementCompilationChallengeReviews','observationRecords','entailmentReviews','environmentDependencies','operationReservations','deliveryRecords','deploymentManifests','disclosureAuthorizations'];
  for(const family of families){const definition=schema.RECORD_SCHEMAS[family];assert(definition,`Missing ${family}.`);const partitions=definition.ownership,all=[...partitions.human,...partitions.humanDecision,...partitions.agent,...partitions.application];assert.equal(all.length,definition.fields.length,`${family} ownership size mismatch.`);assert.equal(new Set(all).size,all.length,`${family} ownership overlap.`);assert.deepEqual([...all].sort(hash.compareUnicodeScalarSequence),[...definition.fields].sort(hash.compareUnicodeScalarSequence),`${family} ownership union does not equal its declared field set.`);for(const [partition,names] of Object.entries(partitions))for(const name of names){const expected={human:'HUMAN',humanDecision:'HUMAN_DECISION',agent:'AGENT',application:'APPLICATION'}[partition];assert.equal(definition.fieldDefinitions[name]?.producer,expected,`${family}.${name} producer metadata disagrees with its ownership partition.`);}}
  return {families,count:families.length};
},['RECORD_SCHEMAS']);
