  authority.projectData.atomicityReviews=[{id:'LEGACY-ATOMICITY',requirementId:requirement.id,status:'ACCEPTED',reviewOutcome:'RESOLVED'}];authority.projectData.normativeClassificationReviews=[{id:'LEGACY-NORMATIVE',requirementId:requirement.id,status:'ACCEPTED',disposition:'ACCEPTED'}];authority.projectData.controlledExceptions=[{id:'LEGACY-EXCEPTION',propositionId:proposition.id,status:'AUTHORIZED'}];authority.projectData.crossHashEvidence=[{id:'LEGACY-CROSS-HASH',artifactId:'MISSING',status:'APPEND_ONLY'}];authority.projectData.redactionRecords=[{id:'LEGACY-REDACTION',sourceArtifactId:'MISSING',redactedArtifactId:'FORGED'}];engine.recalculate(authority);const afterReasons=engine.gate(6,authority).reasons.filter(reason=>reason.includes(requirement.id)).sort();assert.deepEqual(afterReasons,beforeReasons,'A retired audit array changed a current gate.');assert.throws(()=>engine.recordAtomicityReview(authority,{reviewId:'LEGACY-ATOMICITY'}),/only through.*ATOMICITY_CHALLENGE/i);assert.throws(()=>engine.recordNormativeClassificationReview(authority,{reviewId:'LEGACY-NORMATIVE'}),/only through.*DISPOSITION_CHALLENGE/i);assert.equal(engine.records(authority,'artifacts').some(record=>engine.recordId(record,'artifacts')==='FORGED'),false,'A retired redaction record synthesized a canonical artifact.');

  const preserved=Object.fromEntries(legacy.map(name=>[name,structuredClone(authority.projectData[name])])),migrated=core.migrateState(authority);engine.ensureShape(migrated);for(const name of legacy)assert.deepEqual(migrated.projectData[name],preserved[name],`${name} was not preserved as non-operational legacy audit data during migration.`);const beforeDigest=store.projectSha256(migrated);migrated.projectData.atomicityReviews[0].reviewOutcome='FORGED_CHANGED';const afterDigest=store.projectSha256(migrated);assert.notEqual(afterDigest,beforeDigest,'Project/export identity did not bind preserved legacy audit bytes.');migrated.projectData.atomicityReviews=structuredClone(preserved.atomicityReviews);const cloned=store.cloneProjectLineage(migrated,'JOB-LEGACY-AUDIT-CLONE');for(const name of legacy)assert.deepEqual(cloned.project.projectData[name],preserved[name],`${name} was remapped into live authority or lost during clone persistence.`);
  const canonical=spec3();assert.deepEqual(canonical.stage4IndependentChallengeKinds,['ATOMICITY','DISPOSITION'],'The executable canonical Stage 4 challenge route did not cover both retired gate-review replacements.');
  return {legacyCollections:legacy,blankStateInitialized:0,canonicalSchemaFamilies:0,ingestionAccepted:0,gateEffects:0,preservedByMigrationAndClone:legacy.length,canonicalStage4ChallengeKinds:canonical.stage4IndependentChallengeKinds};
